function inferArchiveSubCategory(title = '', category = '') {
    const text = String(title || '');
    const lower = text.toLowerCase();
    if (category === '叛逃人员档案') return '叛逃';
    if (category === '人物档案') return '人物';
    if (category === '事件分支') return '事件';
    if (category === '收容物分支') return '收容物';
    if (/总目录|总则|概念界定|定义|规则|总则与概念界定/.test(text)) return '总则';
    if (/历史溯源|史料|古籍|国际定名/.test(text)) return '历史';
    if (/核心定义|空域分级|规则等级|风险|判定|机制/.test(text)) return '机制';
    if (/认知污染|抹除|回想|路径|偏移|门框|附录/.test(text)) return '机制';
    if (/觉醒者|锚点|登记/.test(text)) return '人物';
    if (/收容物|规程|器材|编号/.test(text)) return '收容物';
    if (/事件|触发|广播|异常|事故/.test(text)) return '事件';
    if (/总局|管控|体系|国家/.test(text)) return '管理';
    if (/叛逃/.test(lower)) return '叛逃';
    return '概览';
}

function inferArchiveSubtitle(title = '', category = '', content = '') {
    if (category !== '人物档案') return '';
    const excerpt = String(content || '');
    const rankMatch = excerpt.match(/档案编号：.*?(正式觉醒者|高阶觉醒者|在逃高阶觉醒者|潜在觉醒者)/i);
    const anchorMatch = excerpt.match(/锚点[^：：]*[:：]\s*([^<\n]+)/i);
    const rank = rankMatch ? rankMatch[1].trim() : '正式觉醒者';
    const anchor = anchorMatch ? anchorMatch[1].trim() : '兽化锚点';
    return `${rank} · ${anchor}`;
}

function inferArchiveImage(title = '', category = '') {
    const titleStr = String(title || '');
    if (category === '人物档案') {
        const match = titleStr.match(/人物档案\s*·\s*(.+)$/);
        const name = match ? match[1].trim() : '';
        if (name) return `images/${name}.png`;
    }
    // 叛逃人员档案：绯燎 / 暮祁 / 衡琬 使用专属立绘
    if (category === '叛逃人员档案') {
        if (titleStr.includes('绯燎')) return 'images/绯燎.png';
        if (titleStr.includes('暮祁')) return 'images/暮祁.png';
        if (titleStr.includes('衡琬')) return 'images/衡琬.png';
    }
    return 'images/default-archive.jpg';
}

DEFAULT_ARCHIVES.forEach(item => {
    if (!item) return;
    item.image = item.image || inferArchiveImage(item.title, item.category);
    item.subCategory = item.subCategory || inferArchiveSubCategory(item.title, item.category);
    item.subtitle = item.subtitle || inferArchiveSubtitle(item.title, item.category, item.content || '');
    if (item.category === '人物档案' && !item.image.includes('.')) {
        item.image = 'images/default-archive.jpg';
    }
    if (!item.tags || !item.tags.length) {
        item.tags = [item.subCategory || '档案', item.category || '档案'];
    }
});

